-- DoorDrop V37: commercial, multilingual welcome email.
-- Keep this message separate from email_verification: registration verification
-- protects access, while this message explains the real DoorDrop service.

UPDATE email_templates
   SET name = 'Bienvenida comercial DoorDrop',
       description = 'Presenta el catálogo, ventas omnicanal, asistencia IA, logística integrada y planes de crecimiento tras crear una cuenta.',
       variables_json = JSON_ARRAY('userName', 'userEmail', 'loginUrl', 'siteName')
 WHERE id = 'auth_welcome';

INSERT INTO email_template_translations
  (id, template_id, language, subject, preheader, body_html, body_text, is_active)
VALUES
('trans_auth_welcome_es', 'auth_welcome', 'es',
 'Bienvenido a DoorDrop, {{userName}}: convierte tus canales en ventas',
 'Publica, conversa, vende y envía desde un solo lugar.',
 '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f1f5f9;font-family:Arial,Helvetica,sans-serif;color:#0f172a"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:24px 10px"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#fff;border:1px solid #e2e8f0;border-radius:24px;overflow:hidden"><tr><td style="padding:30px 32px;background:#0f172a;color:#fff"><div style="font-size:28px;font-weight:800;letter-spacing:-1px">Door<span style="color:#38bdf8">Drop</span></div><div style="margin-top:10px;color:#bae6fd;font-size:11px;font-weight:700;letter-spacing:1.8px">COMERCIO · CONVERSACIONES · LOGÍSTICA</div></td></tr><tr><td style="padding:34px 32px 20px"><div style="display:inline-block;background:#eff6ff;color:#2563eb;border-radius:999px;padding:8px 12px;font-size:11px;font-weight:800;letter-spacing:.8px">TU NEGOCIO, MÁS SIMPLE</div><h1 style="font-size:30px;line-height:1.15;margin:18px 0 12px;color:#0f172a">Bienvenido a DoorDrop, {{userName}}</h1><p style="font-size:16px;line-height:1.65;color:#475569;margin:0">Tu cuenta para <strong>{{userEmail}}</strong> ya fue creada. DoorDrop reúne ventas, conversaciones y envíos para que puedas crecer con control desde un solo panel.</p><p style="text-align:center;margin:28px 0 30px"><a href="{{loginUrl}}" style="display:inline-block;background:#2563eb;color:#fff;padding:15px 26px;border-radius:12px;text-decoration:none;font-weight:800">Entrar a mi panel</a></p><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="33%" valign="top" style="padding:0 6px 0 0"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">🛍️</div><h3 style="font-size:15px;margin:10px 0 6px">Publica y vende</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">Catálogo, marketplace y pedidos en un mismo lugar.</p></div></td><td width="33%" valign="top" style="padding:0 3px"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">💬</div><h3 style="font-size:15px;margin:10px 0 6px">Conversa mejor</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">WhatsApp, Instagram y Facebook con asistencia IA.</p></div></td><td width="33%" valign="top" style="padding:0 0 0 6px"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">📦</div><h3 style="font-size:15px;margin:10px 0 6px">Envía con control</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">Cotizaciones, etiquetas, seguimiento y avisos.</p></div></td></tr></table><div style="margin-top:24px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:18px;padding:22px"><h2 style="font-size:20px;margin:0 0 9px;color:#1d4ed8">Tu asistente IA puede vender por ti</h2><p style="font-size:14px;line-height:1.65;color:#334155;margin:0 0 10px">Cuando conectes tus canales, el asistente puede responder preguntas, entender la intención del cliente, recomendar productos reales, consultar precio y disponibilidad, tomar los datos del pedido y pasar la conversación a una persona cuando sea necesario.</p><p style="font-size:13px;line-height:1.6;color:#475569;margin:0"><strong>Importante:</strong> la IA trabaja con tu catálogo, stock, precios, políticas y reglas configuradas. No inventa productos ni condiciones.</p></div><h2 style="font-size:20px;margin:28px 0 8px">Publica una vez, conecta tus canales</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Puedes organizar tu operación con el Marketplace DoorDrop, Shopify, Wix, WooCommerce y conexiones mediante API. También puedes preparar conexiones con canales como Amazon, eBay y Temu, según el conector y la disponibilidad de cada plataforma.</p><h2 style="font-size:20px;margin:25px 0 8px">Logística integrada</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Compara rutas y servicios de transportistas conectados, genera etiquetas, consulta el tracking y mantén informados a tus clientes desde DoorDrop.</p><div style="margin-top:24px;background:#f8fafc;border-left:4px solid #2563eb;border-radius:10px;padding:16px"><p style="font-size:13px;line-height:1.6;color:#334155;margin:0"><strong>Sin comisión por vender:</strong> DoorDrop no cobra una comisión por la venta del producto. El método de pago elegido puede aplicar sus propios costes de procesamiento o gestión.</p></div><h2 style="font-size:20px;margin:25px 0 8px">Crece a tu ritmo</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Puedes comenzar con el plan que necesitas y activar una suscripción de mayor capacidad cuando aumenten tus envíos, canales, automatizaciones o necesidades de asistencia.</p><p style="font-size:14px;line-height:1.65;color:#475569;margin:18px 0 0">DoorDrop te ayuda a operar desde Italia, España y Estados Unidos, además de gestionar rutas internacionales según la disponibilidad real de los transportistas conectados.</p><p style="font-size:13px;line-height:1.6;color:#64748b;margin:26px 0 0">Si acabas de registrarte con correo y contraseña, confirma primero tu dirección desde el mensaje de verificación para acceder al panel.</p></td></tr><tr><td style="padding:22px 32px;background:#0f172a;color:#cbd5e1;font-size:12px;line-height:1.6">{{siteName}} · Vende mejor. Conversa mejor. Envía mejor.<br><span style="color:#94a3b8">Este mensaje explica las funciones disponibles según la configuración y los conectores activos de tu cuenta.</span></td></tr></table></td></tr></table></body></html>',
 'Hola {{userName}}, bienvenido a DoorDrop. Tu cuenta para {{userEmail}} fue creada. Desde DoorDrop puedes publicar productos, gestionar ventas y conversaciones en WhatsApp, Instagram y Facebook con asistencia IA, y generar cotizaciones, etiquetas, tracking y avisos de envío. La IA utiliza tu catálogo, stock, precios y reglas reales; puede recomendar productos, tomar pedidos y transferir la conversación a una persona. Puedes conectar Marketplace, Shopify, Wix, WooCommerce y API; Amazon, eBay y Temu dependen del conector disponible. DoorDrop no cobra comisión por vender el producto; el método de pago puede aplicar sus propios costes. Los planes de mayor capacidad se activan cuando crecen tus envíos y automatizaciones. Accede aquí: {{loginUrl}}. Si te registraste con correo y contraseña, confirma primero tu email desde el mensaje de verificación.', 1),
('trans_auth_welcome_it', 'auth_welcome', 'it',
 'Benvenuto su DoorDrop, {{userName}}: trasforma i tuoi canali in vendite',
 'Pubblica, conversa, vendi e spedisci da un unico spazio.',
 '<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f1f5f9;font-family:Arial,Helvetica,sans-serif;color:#0f172a"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:24px 10px"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#fff;border:1px solid #e2e8f0;border-radius:24px;overflow:hidden"><tr><td style="padding:30px 32px;background:#0f172a;color:#fff"><div style="font-size:28px;font-weight:800;letter-spacing:-1px">Door<span style="color:#38bdf8">Drop</span></div><div style="margin-top:10px;color:#bae6fd;font-size:11px;font-weight:700;letter-spacing:1.8px">COMMERCIO · CONVERSAZIONI · LOGISTICA</div></td></tr><tr><td style="padding:34px 32px 20px"><div style="display:inline-block;background:#eff6ff;color:#2563eb;border-radius:999px;padding:8px 12px;font-size:11px;font-weight:800;letter-spacing:.8px">IL TUO BUSINESS, PIÙ SEMPLICE</div><h1 style="font-size:30px;line-height:1.15;margin:18px 0 12px;color:#0f172a">Benvenuto su DoorDrop, {{userName}}</h1><p style="font-size:16px;line-height:1.65;color:#475569;margin:0">Il tuo account per <strong>{{userEmail}}</strong> è stato creato. DoorDrop riunisce vendite, conversazioni e spedizioni in un unico pannello.</p><p style="text-align:center;margin:28px 0 30px"><a href="{{loginUrl}}" style="display:inline-block;background:#2563eb;color:#fff;padding:15px 26px;border-radius:12px;text-decoration:none;font-weight:800">Accedi al mio pannello</a></p><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="33%" valign="top" style="padding:0 6px 0 0"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">🛍️</div><h3 style="font-size:15px;margin:10px 0 6px">Pubblica e vendi</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">Catalogo, marketplace e ordini nello stesso spazio.</p></div></td><td width="33%" valign="top" style="padding:0 3px"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">💬</div><h3 style="font-size:15px;margin:10px 0 6px">Parla meglio</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">WhatsApp, Instagram e Facebook con assistenza IA.</p></div></td><td width="33%" valign="top" style="padding:0 0 0 6px"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">📦</div><h3 style="font-size:15px;margin:10px 0 6px">Spedisci con controllo</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">Preventivi, etichette, tracking e avvisi.</p></div></td></tr></table><div style="margin-top:24px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:18px;padding:22px"><h2 style="font-size:20px;margin:0 0 9px;color:#1d4ed8">Il tuo assistente IA può vendere per te</h2><p style="font-size:14px;line-height:1.65;color:#334155;margin:0 0 10px">Dopo aver collegato i tuoi canali, l’assistente può rispondere, capire l’intenzione del cliente, consigliare prodotti reali, verificare prezzo e disponibilità, raccogliere i dati dell’ordine e passare la conversazione a una persona quando serve.</p><p style="font-size:13px;line-height:1.6;color:#475569;margin:0"><strong>Importante:</strong> l’IA lavora con catalogo, stock, prezzi, politiche e regole configurate. Non inventa prodotti o condizioni.</p></div><h2 style="font-size:20px;margin:28px 0 8px">Pubblica una volta, collega i tuoi canali</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Organizza la tua attività con Marketplace DoorDrop, Shopify, Wix, WooCommerce e connessioni API. Puoi preparare anche canali come Amazon, eBay e Temu, in base al connettore e alla disponibilità della piattaforma.</p><h2 style="font-size:20px;margin:25px 0 8px">Logistica integrata</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Confronta rotte e servizi dei corrieri collegati, genera etichette, controlla il tracking e informa i tuoi clienti da DoorDrop.</p><div style="margin-top:24px;background:#f8fafc;border-left:4px solid #2563eb;border-radius:10px;padding:16px"><p style="font-size:13px;line-height:1.6;color:#334155;margin:0"><strong>Nessuna commissione sulla vendita:</strong> DoorDrop non applica una commissione sulla vendita del prodotto. Il metodo di pagamento scelto può applicare i propri costi di elaborazione o gestione.</p></div><h2 style="font-size:20px;margin:25px 0 8px">Cresci al tuo ritmo</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Inizia con il piano che ti serve e attiva una sottoscrizione di maggiore capacità quando aumentano spedizioni, canali, automazioni o assistenza.</p><p style="font-size:14px;line-height:1.65;color:#475569;margin:18px 0 0">DoorDrop ti aiuta a operare dall’Italia, dalla Spagna e dagli Stati Uniti, oltre a gestire rotte internazionali secondo la disponibilità reale dei corrieri collegati.</p><p style="font-size:13px;line-height:1.6;color:#64748b;margin:26px 0 0">Se ti sei registrato con email e password, conferma prima il tuo indirizzo dal messaggio di verifica per accedere al pannello.</p></td></tr><tr><td style="padding:22px 32px;background:#0f172a;color:#cbd5e1;font-size:12px;line-height:1.6">{{siteName}} · Vendi meglio. Comunica meglio. Spedisci meglio.<br><span style="color:#94a3b8">Le funzioni dipendono dalla configurazione e dai connettori attivi del tuo account.</span></td></tr></table></td></tr></table></body></html>',
 'Ciao {{userName}}, benvenuto su DoorDrop. Il tuo account per {{userEmail}} è stato creato. Da DoorDrop puoi pubblicare prodotti, gestire vendite e conversazioni su WhatsApp, Instagram e Facebook con assistenza IA, e generare preventivi, etichette, tracking e avvisi di spedizione. L’IA usa catalogo, stock, prezzi e regole reali; può consigliare prodotti, raccogliere ordini e trasferire la conversazione a una persona. Puoi collegare Marketplace, Shopify, Wix, WooCommerce e API; Amazon, eBay e Temu dipendono dal connettore disponibile. DoorDrop non applica commissioni sulla vendita del prodotto; il metodo di pagamento può applicare i propri costi. I piani di maggiore capacità si attivano quando crescono spedizioni e automazioni. Accedi qui: {{loginUrl}}. Se ti sei registrato con email e password, conferma prima la tua email dal messaggio di verifica.', 1),
('trans_auth_welcome_en', 'auth_welcome', 'en',
 'Welcome to DoorDrop, {{userName}}: turn your channels into sales',
 'Publish, chat, sell and ship from one place.',
 '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f1f5f9;font-family:Arial,Helvetica,sans-serif;color:#0f172a"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:24px 10px"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#fff;border:1px solid #e2e8f0;border-radius:24px;overflow:hidden"><tr><td style="padding:30px 32px;background:#0f172a;color:#fff"><div style="font-size:28px;font-weight:800;letter-spacing:-1px">Door<span style="color:#38bdf8">Drop</span></div><div style="margin-top:10px;color:#bae6fd;font-size:11px;font-weight:700;letter-spacing:1.8px">COMMERCE · CONVERSATIONS · LOGISTICS</div></td></tr><tr><td style="padding:34px 32px 20px"><div style="display:inline-block;background:#eff6ff;color:#2563eb;border-radius:999px;padding:8px 12px;font-size:11px;font-weight:800;letter-spacing:.8px">YOUR BUSINESS, SIMPLIFIED</div><h1 style="font-size:30px;line-height:1.15;margin:18px 0 12px;color:#0f172a">Welcome to DoorDrop, {{userName}}</h1><p style="font-size:16px;line-height:1.65;color:#475569;margin:0">Your account for <strong>{{userEmail}}</strong> has been created. DoorDrop brings sales, conversations and shipping together in one control panel.</p><p style="text-align:center;margin:28px 0 30px"><a href="{{loginUrl}}" style="display:inline-block;background:#2563eb;color:#fff;padding:15px 26px;border-radius:12px;text-decoration:none;font-weight:800">Open my dashboard</a></p><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="33%" valign="top" style="padding:0 6px 0 0"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">🛍️</div><h3 style="font-size:15px;margin:10px 0 6px">Publish and sell</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">Catalog, marketplace and orders in one place.</p></div></td><td width="33%" valign="top" style="padding:0 3px"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">💬</div><h3 style="font-size:15px;margin:10px 0 6px">Have better chats</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">WhatsApp, Instagram and Facebook with AI assistance.</p></div></td><td width="33%" valign="top" style="padding:0 0 0 6px"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">📦</div><h3 style="font-size:15px;margin:10px 0 6px">Ship with control</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">Quotes, labels, tracking and notifications.</p></div></td></tr></table><div style="margin-top:24px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:18px;padding:22px"><h2 style="font-size:20px;margin:0 0 9px;color:#1d4ed8">Your AI assistant can sell for you</h2><p style="font-size:14px;line-height:1.65;color:#334155;margin:0 0 10px">Once your channels are connected, the assistant can answer questions, understand customer intent, recommend real products, check price and availability, collect order details and hand the conversation to a person when needed.</p><p style="font-size:13px;line-height:1.6;color:#475569;margin:0"><strong>Important:</strong> AI works with your configured catalog, stock, prices, policies and rules. It does not invent products or terms.</p></div><h2 style="font-size:20px;margin:28px 0 8px">Publish once, connect your channels</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Run your operation with the DoorDrop Marketplace, Shopify, Wix, WooCommerce and API connections. You can also prepare channels such as Amazon, eBay and Temu, depending on each platform connector and availability.</p><h2 style="font-size:20px;margin:25px 0 8px">Integrated logistics</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Compare routes and services from connected carriers, generate labels, check tracking and keep customers informed from DoorDrop.</p><div style="margin-top:24px;background:#f8fafc;border-left:4px solid #2563eb;border-radius:10px;padding:16px"><p style="font-size:13px;line-height:1.6;color:#334155;margin:0"><strong>No sales commission:</strong> DoorDrop does not charge a commission on product sales. Your chosen payment method may apply its own processing or management costs.</p></div><h2 style="font-size:20px;margin:25px 0 8px">Grow at your pace</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Start with the plan you need and activate a higher-capacity subscription as your shipments, channels, automations or support needs grow.</p><p style="font-size:14px;line-height:1.65;color:#475569;margin:18px 0 0">DoorDrop helps you operate from Italy, Spain and the United States, and manage international routes according to the real availability of connected carriers.</p><p style="font-size:13px;line-height:1.6;color:#64748b;margin:26px 0 0">If you registered with email and password, confirm your address from the verification message before accessing the dashboard.</p></td></tr><tr><td style="padding:22px 32px;background:#0f172a;color:#cbd5e1;font-size:12px;line-height:1.6">{{siteName}} · Sell better. Communicate better. Ship better.<br><span style="color:#94a3b8">Features depend on your account configuration and active connectors.</span></td></tr></table></td></tr></table></body></html>',
 'Hello {{userName}}, welcome to DoorDrop. Your account for {{userEmail}} has been created. DoorDrop helps you publish products, manage sales and conversations on WhatsApp, Instagram and Facebook with AI assistance, and create shipping quotes, labels, tracking and notifications. AI uses your real catalog, stock, prices and rules; it can recommend products, collect orders and transfer the conversation to a person. You can connect Marketplace, Shopify, Wix, WooCommerce and APIs; Amazon, eBay and Temu depend on the available connector. DoorDrop does not charge a product sales commission; the payment method may apply its own costs. Higher-capacity plans can be activated as shipments and automations grow. Open your dashboard: {{loginUrl}}. If you registered with email and password, confirm your email from the verification message first.', 1),
('trans_auth_welcome_fr', 'auth_welcome', 'fr',
 'Bienvenue sur DoorDrop, {{userName}} : transformez vos canaux en ventes',
 'Publiez, échangez, vendez et expédiez depuis un seul espace.',
 '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f1f5f9;font-family:Arial,Helvetica,sans-serif;color:#0f172a"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:24px 10px"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#fff;border:1px solid #e2e8f0;border-radius:24px;overflow:hidden"><tr><td style="padding:30px 32px;background:#0f172a;color:#fff"><div style="font-size:28px;font-weight:800;letter-spacing:-1px">Door<span style="color:#38bdf8">Drop</span></div><div style="margin-top:10px;color:#bae6fd;font-size:11px;font-weight:700;letter-spacing:1.8px">COMMERCE · CONVERSATIONS · LOGISTIQUE</div></td></tr><tr><td style="padding:34px 32px 20px"><div style="display:inline-block;background:#eff6ff;color:#2563eb;border-radius:999px;padding:8px 12px;font-size:11px;font-weight:800;letter-spacing:.8px">VOTRE ACTIVITÉ, SIMPLIFIÉE</div><h1 style="font-size:30px;line-height:1.15;margin:18px 0 12px;color:#0f172a">Bienvenue sur DoorDrop, {{userName}}</h1><p style="font-size:16px;line-height:1.65;color:#475569;margin:0">Votre compte pour <strong>{{userEmail}}</strong> a été créé. DoorDrop réunit ventes, conversations et expéditions dans un seul espace de contrôle.</p><p style="text-align:center;margin:28px 0 30px"><a href="{{loginUrl}}" style="display:inline-block;background:#2563eb;color:#fff;padding:15px 26px;border-radius:12px;text-decoration:none;font-weight:800">Ouvrir mon tableau de bord</a></p><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="33%" valign="top" style="padding:0 6px 0 0"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">🛍️</div><h3 style="font-size:15px;margin:10px 0 6px">Publiez et vendez</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">Catalogue, marketplace et commandes au même endroit.</p></div></td><td width="33%" valign="top" style="padding:0 3px"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">💬</div><h3 style="font-size:15px;margin:10px 0 6px">Échangez mieux</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">WhatsApp, Instagram et Facebook avec assistance IA.</p></div></td><td width="33%" valign="top" style="padding:0 0 0 6px"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">📦</div><h3 style="font-size:15px;margin:10px 0 6px">Expédiez avec contrôle</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">Devis, étiquettes, suivi et notifications.</p></div></td></tr></table><div style="margin-top:24px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:18px;padding:22px"><h2 style="font-size:20px;margin:0 0 9px;color:#1d4ed8">Votre assistant IA peut vendre pour vous</h2><p style="font-size:14px;line-height:1.65;color:#334155;margin:0 0 10px">Une fois vos canaux connectés, l’assistant peut répondre, comprendre l’intention du client, recommander des produits réels, vérifier le prix et la disponibilité, recueillir les détails de la commande et transférer la conversation à une personne si nécessaire.</p><p style="font-size:13px;line-height:1.6;color:#475569;margin:0"><strong>Important :</strong> l’IA utilise votre catalogue, stock, prix, politiques et règles configurés. Elle n’invente ni produits ni conditions.</p></div><h2 style="font-size:20px;margin:28px 0 8px">Publiez une fois, connectez vos canaux</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Organisez votre activité avec le Marketplace DoorDrop, Shopify, Wix, WooCommerce et les connexions API. Vous pouvez aussi préparer des canaux comme Amazon, eBay et Temu, selon le connecteur et la disponibilité de chaque plateforme.</p><h2 style="font-size:20px;margin:25px 0 8px">Logistique intégrée</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Comparez les itinéraires et services des transporteurs connectés, générez des étiquettes, consultez le suivi et informez vos clients depuis DoorDrop.</p><div style="margin-top:24px;background:#f8fafc;border-left:4px solid #2563eb;border-radius:10px;padding:16px"><p style="font-size:13px;line-height:1.6;color:#334155;margin:0"><strong>Aucune commission sur les ventes :</strong> DoorDrop ne facture pas de commission sur la vente du produit. Le moyen de paiement choisi peut appliquer ses propres frais de traitement ou de gestion.</p></div><h2 style="font-size:20px;margin:25px 0 8px">Grandissez à votre rythme</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Commencez avec le plan dont vous avez besoin et activez un abonnement de capacité supérieure lorsque vos expéditions, canaux, automatisations ou besoins d’assistance augmentent.</p><p style="font-size:14px;line-height:1.65;color:#475569;margin:18px 0 0">DoorDrop vous aide à opérer depuis l’Italie, l’Espagne et les États-Unis, et à gérer des itinéraires internationaux selon la disponibilité réelle des transporteurs connectés.</p><p style="font-size:13px;line-height:1.6;color:#64748b;margin:26px 0 0">Si vous vous êtes inscrit avec une adresse e-mail et un mot de passe, confirmez votre adresse depuis le message de vérification avant d’accéder au tableau de bord.</p></td></tr><tr><td style="padding:22px 32px;background:#0f172a;color:#cbd5e1;font-size:12px;line-height:1.6">{{siteName}} · Vendez mieux. Communiquez mieux. Expédiez mieux.<br><span style="color:#94a3b8">Les fonctions dépendent de la configuration et des connecteurs actifs de votre compte.</span></td></tr></table></td></tr></table></body></html>',
 'Bonjour {{userName}}, bienvenue sur DoorDrop. Votre compte pour {{userEmail}} a été créé. DoorDrop vous aide à publier vos produits, gérer les ventes et conversations sur WhatsApp, Instagram et Facebook avec une assistance IA, et créer des devis, étiquettes, suivis et notifications d’expédition. L’IA utilise votre catalogue, stock, prix et règles réels ; elle peut recommander des produits, recueillir les commandes et transférer la conversation à une personne. Vous pouvez connecter Marketplace, Shopify, Wix, WooCommerce et des API ; Amazon, eBay et Temu dépendent du connecteur disponible. DoorDrop ne facture pas de commission sur la vente du produit ; le moyen de paiement peut appliquer ses propres frais. Les plans de capacité supérieure peuvent être activés lorsque vos expéditions et automatisations augmentent. Ouvrez votre tableau de bord : {{loginUrl}}. Si vous vous êtes inscrit avec une adresse e-mail et un mot de passe, confirmez d’abord votre e-mail depuis le message de vérification.', 1),
('trans_auth_welcome_de', 'auth_welcome', 'de',
 'Willkommen bei DoorDrop, {{userName}}: Machen Sie Ihre Kanäle zu Verkäufen',
 'Produkte veröffentlichen, chatten, verkaufen und versenden – an einem Ort.',
 '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f1f5f9;font-family:Arial,Helvetica,sans-serif;color:#0f172a"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:24px 10px"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#fff;border:1px solid #e2e8f0;border-radius:24px;overflow:hidden"><tr><td style="padding:30px 32px;background:#0f172a;color:#fff"><div style="font-size:28px;font-weight:800;letter-spacing:-1px">Door<span style="color:#38bdf8">Drop</span></div><div style="margin-top:10px;color:#bae6fd;font-size:11px;font-weight:700;letter-spacing:1.8px">HANDEL · KONVERSATIONEN · LOGISTIK</div></td></tr><tr><td style="padding:34px 32px 20px"><div style="display:inline-block;background:#eff6ff;color:#2563eb;border-radius:999px;padding:8px 12px;font-size:11px;font-weight:800;letter-spacing:.8px">IHR GESCHÄFT, EINFACHER</div><h1 style="font-size:30px;line-height:1.15;margin:18px 0 12px;color:#0f172a">Willkommen bei DoorDrop, {{userName}}</h1><p style="font-size:16px;line-height:1.65;color:#475569;margin:0">Ihr Konto für <strong>{{userEmail}}</strong> wurde erstellt. DoorDrop verbindet Verkäufe, Gespräche und Versand in einem Kontrollbereich.</p><p style="text-align:center;margin:28px 0 30px"><a href="{{loginUrl}}" style="display:inline-block;background:#2563eb;color:#fff;padding:15px 26px;border-radius:12px;text-decoration:none;font-weight:800">Mein Dashboard öffnen</a></p><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="33%" valign="top" style="padding:0 6px 0 0"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">🛍️</div><h3 style="font-size:15px;margin:10px 0 6px">Veröffentlichen und verkaufen</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">Katalog, Marketplace und Bestellungen an einem Ort.</p></div></td><td width="33%" valign="top" style="padding:0 3px"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">💬</div><h3 style="font-size:15px;margin:10px 0 6px">Besser kommunizieren</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">WhatsApp, Instagram und Facebook mit KI-Unterstützung.</p></div></td><td width="33%" valign="top" style="padding:0 0 0 6px"><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:16px"><div style="font-size:24px">📦</div><h3 style="font-size:15px;margin:10px 0 6px">Kontrolliert versenden</h3><p style="font-size:12px;line-height:1.55;color:#64748b;margin:0">Angebote, Labels, Tracking und Benachrichtigungen.</p></div></td></tr></table><div style="margin-top:24px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:18px;padding:22px"><h2 style="font-size:20px;margin:0 0 9px;color:#1d4ed8">Ihr KI-Assistent kann für Sie verkaufen</h2><p style="font-size:14px;line-height:1.65;color:#334155;margin:0 0 10px">Nach der Verbindung Ihrer Kanäle kann der Assistent Fragen beantworten, Kundenabsichten verstehen, echte Produkte empfehlen, Preis und Verfügbarkeit prüfen, Bestelldaten aufnehmen und bei Bedarf an eine Person übergeben.</p><p style="font-size:13px;line-height:1.6;color:#475569;margin:0"><strong>Wichtig:</strong> Die KI arbeitet mit Ihrem konfigurierten Katalog, Bestand, Preisen, Richtlinien und Regeln. Sie erfindet keine Produkte oder Bedingungen.</p></div><h2 style="font-size:20px;margin:28px 0 8px">Einmal veröffentlichen, Kanäle verbinden</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Nutzen Sie den DoorDrop Marketplace, Shopify, Wix, WooCommerce und API-Verbindungen. Auch Kanäle wie Amazon, eBay und Temu können vorbereitet werden, abhängig vom verfügbaren Connector und der jeweiligen Plattform.</p><h2 style="font-size:20px;margin:25px 0 8px">Integrierte Logistik</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Vergleichen Sie Routen und Services verbundener Versanddienstleister, erstellen Sie Labels, prüfen Sie das Tracking und informieren Sie Ihre Kunden über DoorDrop.</p><div style="margin-top:24px;background:#f8fafc;border-left:4px solid #2563eb;border-radius:10px;padding:16px"><p style="font-size:13px;line-height:1.6;color:#334155;margin:0"><strong>Keine Verkaufsprovision:</strong> DoorDrop berechnet keine Provision auf Produktverkäufe. Die gewählte Zahlungsmethode kann eigene Kosten für Verarbeitung oder Verwaltung berechnen.</p></div><h2 style="font-size:20px;margin:25px 0 8px">Wachsen Sie in Ihrem Tempo</h2><p style="font-size:14px;line-height:1.65;color:#475569;margin:0">Starten Sie mit dem passenden Plan und aktivieren Sie ein leistungsfähigeres Abonnement, wenn Sendungen, Kanäle, Automatisierungen oder Supportbedarf wachsen.</p><p style="font-size:14px;line-height:1.65;color:#475569;margin:18px 0 0">DoorDrop unterstützt Ihren Betrieb in Italien, Spanien und den Vereinigten Staaten sowie internationale Routen nach der tatsächlichen Verfügbarkeit verbundener Versanddienstleister.</p><p style="font-size:13px;line-height:1.6;color:#64748b;margin:26px 0 0">Wenn Sie sich mit E-Mail und Passwort registriert haben, bestätigen Sie Ihre Adresse über die Bestätigungsnachricht, bevor Sie das Dashboard öffnen.</p></td></tr><tr><td style="padding:22px 32px;background:#0f172a;color:#cbd5e1;font-size:12px;line-height:1.6">{{siteName}} · Besser verkaufen. Besser kommunizieren. Besser versenden.<br><span style="color:#94a3b8">Die Funktionen hängen von der Konfiguration und den aktiven Verbindungen Ihres Kontos ab.</span></td></tr></table></td></tr></table></body></html>',
 'Hallo {{userName}}, willkommen bei DoorDrop. Ihr Konto für {{userEmail}} wurde erstellt. DoorDrop hilft Ihnen, Produkte zu veröffentlichen, Verkäufe und Gespräche über WhatsApp, Instagram und Facebook mit KI-Unterstützung zu verwalten sowie Versandangebote, Labels, Tracking und Benachrichtigungen zu erstellen. Die KI nutzt Ihren echten Katalog, Bestand, Preise und Regeln; sie kann Produkte empfehlen, Bestellungen aufnehmen und an eine Person übergeben. Sie können Marketplace, Shopify, Wix, WooCommerce und APIs verbinden; Amazon, eBay und Temu hängen vom verfügbaren Connector ab. DoorDrop berechnet keine Verkaufsprovision; die Zahlungsmethode kann eigene Kosten anwenden. Leistungsfähigere Pläne können aktiviert werden, wenn Sendungen und Automatisierungen wachsen. Dashboard: {{loginUrl}}. Wenn Sie sich mit E-Mail und Passwort registriert haben, bestätigen Sie zuerst Ihre E-Mail über die Bestätigungsnachricht.', 1)
ON DUPLICATE KEY UPDATE
  subject = VALUES(subject), preheader = VALUES(preheader), body_html = VALUES(body_html), body_text = VALUES(body_text), is_active = VALUES(is_active), updated_at = NOW();
